// isDigits reports whether every byte is an ASCII digit, with an
// optional leading +, matching what Atoi accepts in range.
func isDigits(s string) bool {
	s = strings.TrimPrefix(s, "+")
	if s == "" {
		return false
	}
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return false
		}
	}
	return true
}

// retryAfter reads the server's own answer. RFC 9110 allows either a
// delay in seconds or an HTTP-date, and servers send both in the wild.
// The third result says the server asked for longer than max: the
// caller must give up rather than substitute a shorter wait of its own.
func retryAfter(resp *http.Response, max time.Duration) (wait time.Duration, ok bool, tooLong bool) {
	if resp == nil {
		return 0, false, false
	}
	v := resp.Header.Get("Retry-After")
	if v == "" {
		return 0, false, false
	}

	var d time.Duration
	t := strings.TrimSpace(v)
	secs, err := strconv.Atoi(t)
	// A digit string too big for int64 is longer than any cap, not
	// unreadable. Atoi reports ErrRange for it, which is not the same
	// answer as "this is not a number".
	if errors.Is(err, strconv.ErrRange) && isDigits(t) {
		return 0, false, true
	}
	if err == nil {
		// Not secs < 0: Atoi reads "-0" as 0, so the sign has to be
		// caught in the text. RFC 9110 has no negative delay-seconds.
		if strings.HasPrefix(t, "-") {
			return 0, false, false
		}
		// Duration is int64 nanoseconds: 9223372036854775 seconds
		// multiplies out to -808ms, which reads as under max.
		if int64(secs) > int64(max/time.Second) {
			return 0, false, true
		}
		d = time.Duration(secs) * time.Second
	} else if when, err := http.ParseTime(t); err == nil {
		// time.Until saturates rather than wrapping, so no bound here.
		d = time.Until(when)
		if d < 0 {
			d = 0
		}
	} else {
		return 0, false, false
	}

	// max bounds our patience, not the server's answer. Stop rather
	// than clamp to it, which is what urllib3 does: past our patience
	// the work belongs in a queue that survives a deploy, not parked
	// on a connection. The response still carries Retry-After for
	// whoever schedules it.
	if d > max {
		return 0, false, true
	}
	return d, true, false
}

func (c *HTTPClient) Do(req *http.Request) (*http.Response, error) {
	if c.breaker != nil && !c.breaker.allow() {
		return nil, ErrCircuitOpen
	}
	req.Header.Set(ClientVersionHeader, ClientVersion)
	if c.name != "" {
		req.Header.Set(ClientNameHeader, c.name)
	}

	backoffs := c.policy.Backoffs()
	var (
		resp *http.Response
		err  error
	)

	// Deferred so that EVERY exit reports back, including the
	// cancellation return below. allow() hands out the half-open
	// probe and only record() takes it back: a probe that returns
	// without reporting leaves the breaker believing it is still out
	// there, and allow() then refuses everyone for good. Wedged
	// closed is worse than the stampede it replaced, because it does
	// not heal.
	if c.breaker != nil {
		defer func() { c.breaker.record(classify(req, resp, err)) }()
	}

	for attempt := 0; ; attempt++ {
		resp, err = c.http.Do(req)
		if attempt >= len(backoffs) || !c.policy.Retry(req, resp, err) {
			break
		}

		// The server's Retry-After wins: it knows when capacity returns.
		wait := backoffs[attempt]
		d, ok, tooLong := retryAfter(resp, c.maxRetryAfter)
		if tooLong {
			// It asked for longer than we will wait. Hand the
			// response back rather than retrying sooner than it said.
			break
		}
		if ok {
			wait = d
		}

		// Drain and close so the connection returns to the pool reusable.
		if resp != nil {
			_, _ = io.Copy(io.Discard, resp.Body)
			resp.Body.Close()
		}

		// Wait, but not past the caller's deadline. time.Sleep would
		// park this goroutine for the server's full Retry-After - up
		// to maxRetryAfter - after the caller has already given up,
		// and return an answer nobody is waiting for.
		timer := time.NewTimer(wait)
		select {
		case <-req.Context().Done():
			timer.Stop()
			// resp and err are function-scope, so the deferred
			// record() closure sees the cancellation rather than
			// the last response.
			resp, err = nil, req.Context().Err()
			return resp, err
		case <-timer.C:
		}
	}
	return resp, err
}
